import { spacing } from './spacing';

// Grid system — source of truth: Figma node 2081:53035 (Design-Workspace > Grid layouts)
//
//   Mobile/tablet (base–lg, < 1280px): 32px outer container padding
//   Desktop       (xl, ≥ 1280px):      40px outer container padding
//
// Single source of truth for the outer container padding shared by header, footer, and the
// main page content area (see zimmTokens.ts's --zimm-grid-margin-* derivation).

// prettier-ignore
export const breakpoints = {
  base: '0em',
  sm: '30em',       // NOT used (480px)
  md: '48em', // 768px — tablet breakpoint
  lg: '62em',       // NOT used (992px)
  xl: '80em', // 1280px — desktop breakpoint
  '2xl': '96em',    // NOT used (1536px)
} as const;

export const grid = {
