import React, { forwardRef, type CSSProperties } from 'react';
import { chakra, useStyleConfig, type SystemStyleObject } from '@chakra-ui/react';
import { Link as RouterLink } from 'react-router-dom';
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
import { isSafeHref, isInternalHref, buildSafeHref } from 'app/utils/safeHref';
import { GROW_UNDERLINE_SX } from './zimmNavItem.css';

// Allowlist guards against javascript:/data:/vbscript: URIs from CMS-sourced hrefs (XSS vector).
// A single leading / is a same-origin path. // is protocol-relative and resolves off-origin,
// so it is excluded here and must arrive as an explicit https: URL instead.
// isInternalHref (app/utils/safeHref.ts) decides which of those safe hrefs also needs
// useMultiSite()'s buildUrl() below — see that function's own doc comment for the full
// reasoning. Shared with useSafeHref (app/hooks/useSafeHref.ts) and ZimmLink, rather than each
// re-deriving the same classification independently.

const ChakraRouterLink = chakra(RouterLink);

type ZimmNavItemProps = {
  /** Visible label text */
  label: string;
  /**
   * Link destination. When omitted the item renders as a `<button>` with no navigation
   * side-effects — no fragment scroll, no redirect — so placeholder items are safe until
   * real hrefs are sourced from Contentful or the routing layer.
   */
  href?: string;
  /** Marks the item as the genuine current page/route: sets `aria-current="page"` (announced
   *  by assistive tech) and renders the permanent underline. Reserve for real navigation state
   *  — see `visuallyActive` for the underline with no accessible-current implication. */
  active?: boolean;
  /** Renders the same permanent underline as `active` without setting `aria-current` — for
   *  transient UI state that isn't a real current-page indicator (e.g. list-menu-trigger.tsx's
   *  "this L1 item's mega-menu is currently open," which changes on hover/keyboard-open, not
   *  navigation). Announcing `aria-current="page"` for an item the shopper merely hovered would
   *  tell screen-reader users they're on a page they never navigated to. */
  visuallyActive?: boolean;
  /** Inverse mode — white text on a dark background */
  inverse?: boolean;
  /** Explicit recipe variant. Overrides the `inverse` mapping — use for variants that are
   *  neither light nor inverse (e.g. `sizeGuideLink`, the permanently-underlined mobile
   *  "Find your size"). Omit and let `inverse` decide for ordinary navigation links. */
  variant?: 'light' | 'inverse' | 'sizeGuide' | 'sizeGuideLink';
  /** Opt into the left-to-right grow/reverse underline instead of the default fade —
   *  navigation contexts only (top nav bar, mega-menu leaf links). Footer usages keep the
   *  fade. See zimmNavItem.css.ts's GROW_UNDERLINE_SX for the mechanism. */
  growUnderline?: boolean;
  onClick?: (e: React.MouseEvent<HTMLAnchorElement | HTMLButtonElement>) => void;
  /** Forwarded as-is — lets a disclosure trigger (list-menu-trigger.tsx) open on hover without
   *  a wrapping element of its own. */
  onMouseOver?: (e: React.MouseEvent<HTMLAnchorElement | HTMLButtonElement>) => void;
  /** Forwarded as-is — e.g. list-menu-trigger.tsx's Escape-closes-the-open-menu handling. */
  onKeyDown?: (e: React.KeyboardEvent<HTMLAnchorElement | HTMLButtonElement>) => void;
  id?: string;
  /** Below three: forwarded as-is so this atom can be Chakra `PopoverTrigger`'s direct child —
   *  Chakra clones its own `aria-haspopup`/`aria-expanded`/`aria-controls`/`ref` onto whatever
   *  element it wraps, which only works if that element both forwards a ref (see below) and
   *  accepts these explicitly, rather than a wrapping `<Box>` swallowing them silently. */
  'aria-haspopup'?: React.AriaAttributes['aria-haspopup'];
  'aria-expanded'?: boolean;
  'aria-controls'?: string;
  /** Forwarded as-is. `-1` pulls the item out of Tab order without touching its visual
   *  rendering — e.g. megaMenuContent/index.tsx uses this to keep a still-animating panel's
   *  leaf links untabbable until they're actually visible (WCAG 2.4.7), which a CSS-only
   *  approach (opacity/visibility) can't do without also killing the fade transition itself. */
  tabIndex?: number;
  style?: CSSProperties;
  /** Theme-resolved style overrides. Preferred over `style` — token keys resolve. */
  sx?: SystemStyleObject;
  /** Forwarded as-is — e.g. megaMenuContent/index.tsx uses this to mark the two-column
   *  heading link so a sibling CSS selector can target it (Chakra merges it with the
   *  component's own generated class). */
  className?: string;
};

/** Atom — navigation link with bottom-border underline on hover/active. Renders an `<a>` when
 *  `href` is provided and safe, a `<button>` otherwise (no scroll, no redirect for placeholder items).
 *  Mirrors zimm-nav-item web component 1:1.
 *
 *  Forwards its ref to the underlying `<a>`/`<button>` — required so this component can serve
 *  directly as a Chakra `PopoverTrigger`'s child (see list-menu-trigger.tsx). */

=== ZimmNavItem render (button branch) ===
 *  directly as a Chakra `PopoverTrigger`'s child (see list-menu-trigger.tsx). */
export const ZimmNavItem = forwardRef<HTMLAnchorElement | HTMLButtonElement, ZimmNavItemProps>(
  (
    {
      label,
      href,
      active = false,
      visuallyActive = false,
      inverse = false,
      variant: variantProp,
      growUnderline = false,
      onClick,
      onMouseOver,
      onKeyDown,
      id,
      'aria-haspopup': ariaHaspopup,
      'aria-expanded': ariaExpanded,
      'aria-controls': ariaControls,
      tabIndex,
      style,
      sx,
      className,
    },
    ref,
  ) => {
    const { buildUrl } = useMultiSite();
    const variant = variantProp ?? (inverse ? 'inverse' : 'light');
    const styles = useStyleConfig('ZimmNavItem', { variant });
    const mergedSx = growUnderline ? { ...GROW_UNDERLINE_SX, ...sx } : sx;
    // Plain data attribute, not aria-current — see visuallyActive's own doc comment for why the
    // two must stay independent. `|| undefined` (not `visuallyActive`) so React omits the
    // attribute entirely rather than rendering data-visually-active="false".
    const dataVisuallyActive = visuallyActive || undefined;

    if (href && isSafeHref(href)) {
      const commonProps = {
        id,
        'aria-current': active ? ('page' as const) : undefined,
        'aria-haspopup': ariaHaspopup,
        'aria-expanded': ariaExpanded,
        'aria-controls': ariaControls,
        tabIndex,
        'data-visually-active': dataVisuallyActive,
        onClick,
        onMouseOver,
        onKeyDown,
        __css: styles,
        sx: mergedSx,
        style,
        className,
      };

      // Internal path: prefix with the current site/locale and route client-side, same as base
      // SFCC's own Link component (see overrideStyling.md's ZimmNavItem fix rationale).
      // buildSafeHref (not a raw buildUrl(href) call) so the value it prefixes is normalised the
      // same way isSafeHref/isInternalHref already classified it — see that function's own doc
      // comment for why a raw href here could disagree with the classification above it.
      if (isInternalHref(href)) {
        return (
          <ChakraRouterLink
            ref={ref as React.Ref<HTMLAnchorElement>}
            to={buildSafeHref(href, buildUrl)}
            {...commonProps}
          >
            <span>{label}</span>
          </ChakraRouterLink>
        );
      }

      // External / tel: / mailto: / #fragment — rendered exactly as before, unprefixed.
      return (
        <chakra.a ref={ref as React.Ref<HTMLAnchorElement>} href={href} {...commonProps}>
          <span>{label}</span>
        </chakra.a>
      );
    }

    return (
      <chakra.button
        ref={ref as React.Ref<HTMLButtonElement>}
        id={id}
        type="button"
        aria-current={active ? 'page' : undefined}
        aria-haspopup={ariaHaspopup}
        aria-expanded={ariaExpanded}
        aria-controls={ariaControls}
        tabIndex={tabIndex}
        data-visually-active={dataVisuallyActive}
        onClick={onClick}
        onMouseOver={onMouseOver}
        onKeyDown={onKeyDown}
        __css={styles}
        sx={mergedSx}
        style={style}
        className={className}
      >
